const screens=[];
function add(id,theme,body,{title='',footer='',className='',headerMarkup='',overlay=''}={}){screens.push({id,theme,html:`<div class="screen ${className}" data-theme="${theme}" data-default-theme="${theme}" ${className.includes('viewer')?'data-theme-locked="true"':''} aria-label="${title||id}">${status}${headerMarkup|| (title?header(title):'')}${body}${footer?`<div class="phone-footer">${footer}</div>`:''}${homebar}${overlay}</div>`});}
const body=(html,cls='')=>`<div class="screen-body ${cls}">${html}</div>`;
const footer=(label,note='',variant='')=>`${note?`<p class="hint">${note}</p>`:''}${btn(label,variant)}`;
const termsLinks=`<span class="text-link">用户协议</span> · <span class="text-link">隐私政策</span> · <span class="text-link">AI 内容免责声明</span>`;
const legalTabs=(active)=>`<div class="legal-tabs">${['用户协议','隐私政策','AI 内容免责声明'].map(s=>`<span class="${s===active?'active':''}">${s}</span>`).join('')}</div>`;
const listRow=(ico,title,detail='')=>`<div class="list-row"><span class="row-icon">${icon(ico)}</span><div class="grow"><div class="label">${title}</div>${detail?`<p class="hint">${detail}</p>`:''}</div>${icon('chevron')}</div>`;
add('privacy','studio',body(`<div class="privacy-art">${photo(1)}${photo(5)}</div><div class="stack"><span class="section-label">WELCOME TO YOUR STUDIO</span><h2 class="display-title">先认识衣序，<br>再开始创作。</h2><p class="subtitle">隐私提示</p><p class="muted" style="font-size:13px;line-height:25px">衣序会处理你的账号、上传素材与生成记录，用于提供穿搭创作服务。生成所需内容会交由第三方模型服务处理。你可以查看、删除这组片或注销账号。</p><p class="small text-link">查看《用户协议》和《隐私政策》</p><p class="hint">请仅上传有权使用的素材与肖像。</p></div>`),{footer:`${btn('同意并继续')}${btn('暂不使用','link')}`});
for(const [id,n,title,desc,idx] of [
 ['guide-start',4,'一件衣服，<br>一组大片','从衣服出发，把灵感、脚本和画面，慢慢整理成你的下一篇穿搭笔记。',0],
 ['guide-mode',6,'一键出片，<br>或者一步步来','交给我们，全套图文和视频一次出好，中途可以接手。想亲自打磨，就选沉浸编导。',1],
 ['guide-points',8,'正式出图和视频<br>会扣点，由你确认','开拍前看清预估。沉浸编导逐步确认，一键出片按开拍时的说明自动推进。发布时请勾选 AI 内容声明。',2]
])add(id,'studio',`<div class="guide-hero">${img(n,'','衣序穿搭成片示意')}</div><span class="guide-photo-label">衣序 / INSPIRATION ${String(idx+1).padStart(2,'0')}</span><span class="ai-note">AI生成</span><div class="spacer"></div><div class="guide-content"><div class="guide-counter">${[0,1,2].map(i=>`<span class="${i===idx?'active':''}"></span>`).join('')}</div><h2 class="display-title" style="font-size:${idx===2?'29':'34'}px">${title}</h2><p>${desc}</p></div>`,{className:'guide',footer:btn(idx===2?'进入衣序':'继续')});
add('login','studio',body(`<div class="stack" style="padding-top:46px">${brand}<div style="margin:16px 0 24px"><span class="section-label">BACK TO THE STUDIO</span><h2 class="display-title" style="margin-top:12px">你的灵感，<br>接着拍。</h2></div><div class="segmented"><span class="active">登录</span><span>注册</span></div>${field('用户名','输入用户名')}${field('密码','至少 8 位 · ••••••••')}<div class="between"><span class="hint">欢迎回到你的片场</span><span class="text-link label">忘记密码？</span></div>${btn('登录')}<p class="hint" style="text-align:center">${termsLinks}</p></div>`),{footer:'<p class="hint" style="text-align:center;padding:10px 0">衣序 · 演示版</p>'});
add('register','studio',body(`<div class="stack">${brand}<h2 class="display-title" style="font-size:30px">给灵感一个片场。</h2><div class="segmented"><span>登录</span><span class="active">注册</span></div>${field('用户名','3–32 位')}${field('密码','至少 8 位')}${field('昵称（选填）','你希望怎么被称呼')}<div class="checkbox-row"><span class="checkbox"></span><span>我已阅读并同意<br><span class="text-link">《用户协议》</span>和<span class="text-link">《隐私政策》</span></span></div><div class="notice">请先阅读并勾选协议与隐私政策。</div>${btn('注册','', 'disabled')}<p class="hint">注册后会展示一次恢复码，请妥善保存。</p></div>`));
add('recovery','paper',body(`<div class="stack" style="padding-top:24px"><span class="avatar-placeholder">${icon('key')}</span><span class="section-label">KEEP THIS SOMEWHERE SAFE</span><h2 class="page-title">保存你的恢复码</h2><p class="muted" style="font-size:14px;line-height:26px">这是唯一的找回方式。恢复码只在这一次展示，请保存在只有你能访问的地方。</p><div class="code">DEMO-ONLY-CODE</div><p class="hint">设计占位 · 实际格式 xxxx-xxxx-xxxx</p>${btn(`${icon('copy')} 复制恢复码`,'ghost')}<div class="notice warning">不要把恢复码发给任何人。忘记密码时，需要用户名和恢复码。</div><div class="notice success">✓ 已复制，请确认已另行保存。</div></div>`),{title:'保存恢复码',footer:footer('我已保存','保存后进入首页；恢复成功后也会展示新的恢复码。')});
add('home','studio',body(`<div class="home-head">${brand}<span class="icon-button" aria-label="设置">${icon('settings')}</span></div><div class="between"><div><p class="section-label">A LITTLE INSPIRATION</p><h2 class="section-title" style="margin-top:4px">灵感墙</h2></div><span class="small muted">点开，看细节 ↗</span></div><div class="wall"><div class="column">${photo(1)}</div><div class="column">${photo(10)}</div></div><div class="banner">${icon('check')}<span>刚刚出好 · 咖啡馆午后</span><span style="margin-left:auto">查看 →</span></div><div class="between"><h2 class="section-title">进行中</h2><span class="small muted">1 组</span></div><div class="home-project">${photo(3)}<div class="grow"><h3>自由创作 · 松弛通勤</h3><p>出图中 2/3</p><div class="progress-track" style="margin-top:5px"><span></span></div></div><span class="label" style="color:var(--color-text-brand)">继续 →</span></div><div class="between"><h2 class="section-title">我的片场</h2><span class="small muted">全部 →</span></div><div class="home-project">${photo(9)}<div><h3>自由创作 · 复古港风</h3><p>全套已出好</p></div></div>`, 'home-body'),{footer:btn(`${icon('plus')} 拍一组新片`)});
const tags=['松弛通勤','老钱极简','法式慵懒','街头胶片','杂志大片','咖啡馆午后','闪光灯夜拍','复古港风'];
for(const [id,auto] of [['new-auto',true],['new-guided',false]])add(id,'studio',body(`<h2 class="display-title">一件衣服，一组大片</h2><div><div class="segmented"><span class="${auto?'active':''}">一键出片</span><span class="${!auto?'active':''}">沉浸编导</span></div><div class="between" style="margin-top:6px"><p class="mode-description">${auto?'全套图文和视频一次出好，中途可以接手。':'聊灵感、定脚本、挑图改图，每一步你说了算。'}</p><span class="icon-button" aria-label="了解创作模式">${icon('help')}</span></div></div><div class="stack-xs"><div class="material-row"><span class="material-icon">${icon('shirt')}</span><div class="grow"><h3>衣服 <span style="color:var(--color-text-brand)">必填</span></h3><p>${auto?'已选 1 张 · 浅色短袖衬衫':'上传衣服原图，保留清晰细节'}</p></div>${icon('plus')}</div><div class="material-row"><span class="material-icon">${icon('person')}</span><div class="grow"><h3>出镜的人 <span class="muted">选填</span></h3><p>默认使用档案照片；没有则用 AI 模特</p></div>${icon('chevron')}</div><div class="material-row"><span class="material-icon">${icon('image')}</span><div class="grow"><h3>参考图 <span class="muted">选填 · 最多 3 张</span></h3><p>${auto?'一键出片建议上传，帮助确定风格':'喜欢的光线、构图或氛围'}</p></div>${icon('plus')}</div></div><div class="row">${field('品牌（选填）','自由创作','half')}${field('描述你的风格','自然、轻松，不穿高跟鞋','half')}</div><div><div class="between"><span class="label">风格词条 <span class="muted small">已选 1/6</span></span><span class="text-link small">换一批</span></div>${chips(tags)}</div>${field('这次想拍什么','周末去咖啡馆，拍一组日常穿搭。')}${field('这组片名称（可改）','自由创作 · 松弛通勤')}`, 'stack-sm new-body'),{title:'拍一组新片',footer:footer(auto?'开拍，全自动 · 约 48 点':'开拍，先聊灵感',auto?'预览 15 + 正式出图约 18 + 视频 15 点 · 今日还有 585 点':'先聊灵感；正式出图前会确认点数。',!auto?'disabled':'')});
add('direction','paper',body(`<div class="stack-sm"><div class="user-bubble">想要自然一点，像周末随手拍的。</div><div><p class="assistant-label">衣序 · 编导间</p><p style="font-size:14px;line-height:25px">这件衬衫适合轻松的日常场景。给你两个方向，先挑一个喜欢的。</p></div><div class="card direction-card selected">${photo(5)}<div class="grow">${badge('推荐方向','brand')}<h3 class="subtitle" style="margin-top:8px">咖啡馆午后</h3><p>窗边自然光 · 米白与木色<br>拿起咖啡，不看镜头</p><p>让亚麻纹理成为主角。</p></div></div><div class="card direction-card">${photo(2)}<div class="grow"><h3 class="subtitle">街角慢走</h3><p>35mm 街拍 · 微微逆光<br>一边走，一边整理衣角</p><p>更有胶片里的随意感。</p></div></div><div class="between"><span class="text-link label">换一组</span><span class="hint">约 15 点 · 含 2–3 张预览</span></div>${trace('用了 提方向 · 4.8s · 0.3 点')}</div>`),{title:'编导间',headerMarkup:header('编导间',badge('沉浸编导')),footer:`${btn('就选咖啡馆午后')}${composer('也可以说：再松弛一点…')}`});
add('script','paper',body(`<div class="stack-sm"><p class="assistant-label">衣序 · 编导间</p><p style="font-size:14px;line-height:25px">围绕咖啡馆午后，先出封面，再让其余画面延续同一束光。</p><div class="card"><div class="between"><h2 class="subtitle">这组片的脚本</h2>${badge('草稿 v2','brand')}</div><p class="hint" style="margin-top:8px">标题备选</p><p class="subtitle" style="margin:4px 0 12px">把周末穿得松弛一点</p><div class="shot-row"><span class="shot-number">01</span><div><div class="between"><h3 class="label">窗边的半身封面</h3>${badge('封面锚点')}</div><p>50mm · 侧窗自然光<br>手捧咖啡，微微侧身，不看镜头。<br>配文：慢下来，也很好。</p></div></div><div class="shot-row"><span class="shot-number">02</span><div><h3 class="label">走向座位的瞬间</h3><p>35mm · 略低机位 · 轻微动态模糊<br>衬衫自然垂落，保留面料纹理。</p></div></div><div class="shot-row"><span class="shot-number">03</span><div><h3 class="label">衣角与咖啡的细节</h3><p>50mm · 半身裁切<br>整理衣角，拍清袖口和纽扣。</p></div></div><p class="hint" style="margin-top:12px">视频：5 秒，抬起杯子的自然动作。</p></div><div class="between"><span class="text-link small">查看脚本历史</span><span class="hint">v1 可恢复</span></div>${trace('用了 写脚本 · 4.8s · 0.3 点')}</div>`),{title:'编导间',footer:`${footer('确认脚本，出 3 张图 · 约 18 点','预计 18 点 · 今日还有 585 点。视频会单独确认。')}${composer('说说想改哪一幕…')}`});
add('auto','paper',body(`<div class="stack"><div class="notice">一键出片进行中 · 可以离开，完成后会通知你。</div><div class="steps">${['方向','脚本','图片','笔记','视频'].map((s,i)=>`<span class="step ${i<2?'done':i===2?'current':''}">${s}</span>`).join('')}</div><div class="card stack-sm"><div class="between"><h2 class="subtitle">正在出图 2/3</h2>${badge('一键出片','brand')}</div><div class="progress-track"><span></span></div><p class="hint">封面已出好，其余镜头沿用人物与光线。</p><div class="photo-grid three">${photo(5)}${photo(7)}<div class="photo" style="display:flex;align-items:center;justify-content:center"><div class="stack-xs" style="padding:10px;width:100%"><div class="skeleton"></div><div class="skeleton" style="width:70%"></div><span class="hint">出图中</span></div></div></div></div><div><p class="assistant-label">衣序 · 进度播报</p><p style="font-size:14px;line-height:26px">封面好了。接下来完成另外两个镜头，再整理笔记和 5 秒视频。</p>${trace('用了 出图 · 已完成 2 张 · 10 点')}</div><div class="between"><span class="hint">开拍时预估约 48 点</span><span class="hint">今日还有 555 点</span></div></div>`),{title:'编导间',footer:`<p class="hint">接手后，从下一个确认点起由你决定；已经在跑的任务会继续。</p>${btn('我来接手','ghost')}${composer('补充一句想法…')}`});
add('auto-paused','paper',body(`<div class="stack"><div class="steps">${['方向','脚本','图片','笔记','视频'].map((s,i)=>`<span class="step ${i<2?'done':i===2?'current':''}">${s}</span>`).join('')}</div><div class="notice warning"><strong>已转为沉浸编导</strong><br>第 3 张图未能生成，已停在出图阶段。</div><div class="photo-grid three">${photo(5)}${photo(7)}<div class="photo" style="display:flex;align-items:center;justify-content:center;border:1px dashed var(--color-border-input)"><div class="small" style="text-align:center">${icon('refresh')}<p>出图失败</p></div></div></div><div><p class="assistant-label">衣序 · 编导间</p><p style="font-size:14px;line-height:26px">前两张已保留。你可以继续聊来调整脚本，也可以先用已完成的图片继续挑图。</p></div><div class="card stack-sm"><div class="between"><span class="label">下一步由你决定</span></div><p class="hint">失败任务退点。再次生成前会重新展示预估并由你确认。</p>${btn('继续聊，调整这组片')}${btn('先挑已完成的图片','ghost')}</div><div class="offline-card">${icon('wifi')} 网络中断时保留已知进度。<br>连接恢复后重新读取这组片，不重复开拍。</div></div>`),{title:'编导间',footer:composer()});
add('viewer','studio',body(`<div class="viewer-photo">${img(5,'','镜头 1 第 2 版：浅色衬衫袖口仍有卷起')}${badge('未改到位','warning')}</div><div class="viewer-caption"><div class="between"><span>镜头 01 · v2</span>${badge('人像 92')}</div><p class="muted" style="margin-top:6px">袖口仍有卷起，未完全放平。笔记仍采用 v1。</p></div><div class="versions"><div class="version">${img(5)}<p>v1 · 已采用</p></div><div class="version active">${img(5)}<p>v2 · 未通过</p></div><span class="hint">← 版本链<br>左右滑动</span></div><div class="viewer-tools"><span>${icon('compare')}前后对比</span><span>${icon('quote')}引用</span><span>${icon('download')}保存</span></div><p class="hint" style="padding:0 24px">长按：局部改 / 整张改 / 引用到对话 / 对比版本 / 保存到相册</p><p class="hint" style="padding:8px 24px">双指缩放 · 双击放大 · 左右切换图片</p>`),{title:'1 / 3',className:'viewer',footer:`<div class="row">${btn('局部改','secondary')}${btn('再试一次 · 约 5 点','ghost')}</div><p class="small text-link" style="min-height:44px;display:flex;align-items:center;justify-content:center">仍然采用</p>`});
add('local-edit','studio',body(`<div class="viewer-photo" style="height:380px">${img(5,'','涂抹选区在衬衫右袖口处')}<span class="mask-patch" aria-label="袖口涂抹选区"></span></div><div class="viewer-tools"><span style="color:var(--color-text-brand)">${icon('pencil')}涂抹</span><span>${icon('select')}框选</span><span>${icon('undo')}撤销</span><span>${icon('close')}清空</span></div><div class="brushbar"><span>笔刷</span><span class="slider"></span><span>中</span></div><div class="stack-xs" style="padding:8px 24px"><div class="chips"><span class="chip selected">袖口放下来</span><span class="chip">去掉吊牌</span><span class="chip">背景亮一点</span></div><div class="input" style="font-size:13px">把圈选的袖口放平，保持原来的短袖。</div><p class="hint">只改圈选区域；没有圈选时为整张改。</p></div>`),{title:'涂抹局部改',className:'viewer',footer:footer('提交局部改 · 约 5 点','今日还有 555 点 · 原图与历史版本保留')});
add('select','paper',body(`<div class="stack"><div><h2 class="page-title">把喜欢的，留下来。</h2><p class="hint" style="margin-top:8px">每个镜头保留一个版本，拖动调整顺序。</p></div><div class="photo-grid">${[5,7,9].map((n,i)=>`<div><div class="photo selected">${img(n)}${badge('AI生成','ai')}<span class="count-dot">${i+1}</span></div><div class="between" style="margin-top:8px"><span class="label">镜头 0${i+1} · ${i===1?'v2':'v1'}</span></div>${badge(i===1?'手动采用':'已采用',i===1?'warning':'success')}</div>`).join('')}<div class="card subtle stack-xs" style="align-self:start"><h3 class="label">选图说明</h3><p class="hint">未改到位的版本不会自动入稿。</p><p class="hint">点图查看版本；「仍然采用」需确认原因。</p></div></div><div class="notice warning">镜头 02 为手动采用；预览和发布清单也会保留标记。</div></div>`),{title:'挑图',footer:footer('采用这 3 张，整理笔记','已选 3 张 · 顺序与封面会带入笔记')});
const adoptBackground=body(`<div class="stack">${photo(5,'large')}${badge('未改到位','warning')}<h2 class="section-title">镜头 02 · v2</h2></div>`);
add('adopt-confirm','paper',adoptBackground,{title:'挑图',overlay:`<div class="scrim"><div class="sheet"><span class="sheet-handle"></span>${badge('未改到位','warning')}<h3>仍然采用这个版本？</h3><p>检查结果：袖口仍有卷起，未完全放平。</p><p>采用后，这张图会进入笔记和视频候选；预览与发布清单会标记「手动采用」。</p>${btn('确认，仍然采用')}${btn('返回，保留原版','ghost')}</div></div>`});
add('note','paper',body(`<div class="stack-sm"><div class="note-cover">${photo(5,'','把周末穿得松弛一点')}</div><div class="photo-grid three">${[5,7,9].map((n,i)=>`<div>${photo(n)}${i===1?badge('手动采用','warning'):`<p class="hint">${i===0?'封面':'镜头 03'}</p>`}</div>`).join('')}</div><div class="note-field"><div class="between"><span class="hint">标题</span><span class="hint">9 / 20</span></div><h3>把周末穿得松弛一点</h3></div><div class="note-field"><p>周末的咖啡馆，适合一件轻盈的衬衫。<br>米白与木色，舒服得刚刚好。</p></div><div class="chips"><span class="chip">#松弛通勤 ×</span><span class="chip">#日常穿搭 ×</span><span class="chip">＋ 话题</span></div><div class="checkbox-row"><span class="checkbox checked">${icon('check')}</span><span>AI 生成内容 · 发布时请同步勾选平台声明</span></div><div class="between"><span class="text-link small">重新选图</span><span class="text-link small">恢复服务端版本</span></div></div>`),{title:'笔记预览',headerMarkup:header('笔记预览','保存草稿'),footer:btn('准备发布')});
add('note-conflict','paper',body(`<div class="stack"><div class="notice warning"><strong>笔记有新版本</strong><p style="margin-top:6px">你有尚未发布的本地修改。选图变化后，编导间已整理了新的笔记。</p><div class="row" style="margin-top:10px">${btn('保留我的修改','ghost')}${btn('采用新版本','secondary')}</div></div><div class="card"><div class="between"><span class="label">我的本地草稿</span>${badge('有修改','brand')}</div><h2 class="section-title" style="margin-top:14px">在咖啡香里，过个慢周末</h2><p style="font-size:13px;line-height:25px;margin-top:12px">比起赶路，今天更想在窗边坐一会儿。<br>一件轻松的衬衫，就足够了。</p></div><div class="photo-grid three">${photo(5)}${photo(7)}${photo(9)}</div><div class="notice success">✓ 本地草稿已保存</div><p class="hint">保留我的修改：继续使用当前文案和顺序。<br>采用新版本：用新笔记替换本地草稿。<br>操作前不会自动清空你的修改。</p><span class="text-link small" style="min-height:44px;display:flex;align-items:center">恢复服务端版本</span></div>`),{title:'笔记预览',footer:btn('准备发布')});
add('publish','paper',body(`<div class="stack"><span class="section-label">READY WHEN YOU ARE</span><h2 class="page-title">发布前，再看一眼。</h2><div class="photo-grid three">${photo(5)}${photo(7)}${photo(9)}</div><div class="card stack"><h3 class="subtitle">发布清单</h3><div class="check-list"><div>${icon('check')}<span>图片 3 张 · 按当前顺序保存</span></div><div>${icon('check')}<span>5 秒视频 · 已就绪</span></div><div>${icon('check')}<span>标题、正文与话题 · 待复制</span></div><div>${icon('check')}<span>已勾选 AI 内容声明</span></div></div><div class="notice warning">镜头 02 · 手动采用<br>检查结果：袖口仍有卷起，未完全放平。</div></div><p class="hint">准备发布会复制文案、保存图片和视频，再打开系统分享面板。请在发布平台核对内容并勾选 AI 声明。</p><div class="offline-card">相册权限未开启时，可去系统设置开启，再继续保存。</div></div>`),{title:'发布清单',footer:btn('准备发布')});
add('video','paper',body(`<div class="stack"><div class="between"><div><p class="section-label">THAT'S A WRAP</p><h2 class="page-title">这组片，拍好了。</h2></div>${badge('视频就绪','success')}</div><div class="video-cover">${img(5,'','5 秒视频的封面示意')}<span class="play">${icon('play')}</span><span class="badge ai">AI生成</span><div class="video-time"><span>00:01</span><span class="progress-track"><span></span></span><span>00:05</span></div></div><div class="between"><span class="label">5 秒 · 720P · 带音轨</span><span class="text-link small">保存视频</span></div><p class="hint">源图：镜头 01 · v1 · 已采用<br>视频阶段已定稿，图片顺序与版本不再变更。</p></div>`),{title:'视频就绪',footer:btn('查看发布清单')});
add('points','paper',body(`<div class="stack"><p class="assistant-label">衣序 · 编导间</p><h2 class="page-title">脚本已准备好。</h2><p class="muted">3 个镜头，先从封面开始。</p><div class="card"><div class="between"><h3 class="subtitle">咖啡馆午后 · 脚本 v2</h3>${badge('待确认','brand')}</div><p class="hint" style="margin-top:12px">窗边半身封面 / 走向座位 / 衣角细节</p></div><div class="notice warning"><strong>今日点数不够了，明天 00:00 恢复</strong><p style="margin-top:8px">预计 18 点 · 今日还有 8 点<br>脚本和素材已保留，可以继续聊灵感。</p></div>${btn('确认脚本，出 3 张图 · 约 18 点','','disabled')}<div class="card subtle"><h3 class="label">视频会单独确认</h3><p class="hint" style="margin-top:8px">生成 5 秒视频 · 预计 15 点<br>只有你确认后才会开始。</p></div>${btn('先回我的片场','ghost')}</div>`),{title:'编导间',footer:composer()});
add('projects','studio',body(`<div class="stack"><div><h2 class="display-title" style="font-size:30px">每一组，都在这里。</h2><p class="hint" style="margin-top:8px">按最近更新排序 · 下拉刷新</p></div><div class="input row" style="font-size:13px">${icon('search')}按标题或品牌搜索</div>${[ [3,'自由创作 · 松弛通勤','等你确认脚本','brand'],[5,'自由创作 · 咖啡馆午后','笔记已就绪，等你看','success'],[9,'自由创作 · 复古港风','全套已出好',''] ].map(([n,t,s,tone])=>`<div class="card row">${photo(n,'mini')}<div class="grow"><h3 class="label">${t}</h3><div style="margin-top:8px">${badge(s,tone)}</div></div>${icon('chevron')}</div>`).join('')}<p class="hint">左滑或长按可删除这组片。</p><div class="card stack-sm" style="border-color:var(--color-status-danger)"><h3 class="subtitle">删除这组片？</h3><p class="hint">将删除消息、任务与生成媒体。上传的衣服原图保留。此操作无法撤销。</p><div class="row">${btn('取消','ghost')}${btn('删除这组片','danger')}</div></div></div>`),{title:'我的片场',footer:btn(`${icon('plus')} 拍一组新片`)});
add('profile','paper',body(`<div class="stack"><p class="hint">你的照片和偏好，会成为下一组片的起点。</p>${field('昵称','小序')}<div class="card stack-sm"><div class="between"><h2 class="subtitle">出镜的人</h2><span class="text-link small">上传照片</span></div><div class="row"><span class="material-icon" style="width:72px;height:96px">${icon('person')}</span><div><p class="label">本人照片</p><p class="hint">上传后可设默认、删除<br>仅用你有权使用的肖像</p></div></div><p class="hint">当前未上传，新片将使用 AI 模特。</p></div><div class="row">${field('身高（选填）','168 cm','half')}${field('体型描述（选填）','按你的习惯描述','half')}</div>${field('风格偏好（选填）','喜欢松弛感，不穿高跟鞋')}<p class="hint">新片默认使用档案的第一张照片，也可在开拍前更换。</p><div class="notice success">✓ 偏好已保存，下次开拍会参考。</div></div>`),{title:'我的形象',footer:btn('保存我的形象')});
add('settings','paper',body(`<div class="stack"><div class="account-hero"><span class="avatar-placeholder">${icon('person')}</span><div><h2 class="section-title">小序</h2><p class="hint">账号 xiaoxu</p></div></div><div class="card"><div class="between"><span class="label">今日点数</span><strong>585 <span class="hint">/ 600 点</span></strong></div><div class="progress-track" style="margin:12px 0 8px"><span style="width:97.5%"></span></div><p class="hint">明天 00:00 恢复</p></div><div>${listRow('person','我的形象','照片、昵称与风格偏好')}${listRow('lock','账号与安全','密码、恢复码与注销')}${listRow('file','协议与隐私')}${listRow('help','关于衣序')}</div>${btn('退出登录','ghost')}<p class="hint">退出前确认本地草稿已保存。</p></div>`),{title:'设置'});
add('security','paper',body(`<div class="stack"><div class="card"><p class="hint">当前账号</p><h2 class="section-title" style="margin-top:8px">xiaoxu</h2></div><div>${listRow('lock','修改密码','修改后，其他旧登录会失效')}${listRow('key','恢复码','重新生成后，旧码立即失效')}${listRow('file','协议与隐私','用户协议 / 隐私政策 / AI 内容免责声明')}</div><div class="notice">恢复码是唯一的账号找回方式，请妥善保存。</div><div style="margin-top:44px">${listRow('close','注销账号','删除全部片场与媒体，无法撤销')}</div></div>`),{title:'账号与安全'});
add('password','paper',body(`<div class="stack"><h2 class="page-title">换一个安心的密码。</h2><p class="hint">修改后，当前设备保持登录，其他旧登录将失效。</p>${field('当前密码','••••••••')}${field('新密码','至少 8 位')}<div class="notice">不要与其他服务使用相同密码。</div>${btn('修改密码')}<div class="notice success">✓ 密码已修改，当前设备已更新登录。</div></div>`),{title:'修改密码'});
add('recovery-reset','paper',body(`<div class="stack"><span class="avatar-placeholder">${icon('key')}</span><h2 class="page-title">重新生成恢复码</h2><p class="muted" style="font-size:14px;line-height:26px">如果恢复码丢失或可能泄露，请验证当前密码后重新生成。</p>${field('当前密码','输入当前密码')}<div class="notice warning">生成新码后，旧恢复码立即失效。新码也只展示一次。</div>${btn('验证并生成新恢复码')}<div class="card subtle"><h3 class="label">接下来</h3><p class="hint" style="margin-top:8px">进入「保存恢复码」，复制并点「我已保存」后返回。</p></div></div>`),{title:'恢复码'});
add('forgot','paper',body(`<div class="stack"><h2 class="page-title">用恢复码，找回账号。</h2><p class="hint">验证成功后重置密码并登录，同时生成新的恢复码。</p>${field('用户名','xiaoxu')}${field('恢复码','xxxx-xxxx-xxxx','error')}${field('新密码','至少 8 位')}<p class="error-text">账号或恢复码不正确，请核对后重试。</p>${btn('验证并重置密码')}<div class="notice warning">恢复成功后，旧登录与旧恢复码失效。请保存新恢复码。</div><p class="hint">请使用注册时保存的恢复码。当前不支持短信或邮箱验证。</p></div>`),{title:'忘记密码'});
add('delete','paper',body(`<div class="stack"><span class="avatar-placeholder" style="color:var(--color-status-danger)">${icon('close')}</span><h2 class="page-title">注销账号前，请确认。</h2><p style="font-size:14px;line-height:26px">账号 xiaoxu 将被注销。该账号下的全部片场、消息、任务和媒体会被清理，所有登录立即失效。</p><div class="notice warning">注销后无法找回这些内容。请先保存你需要的成片与笔记。</div>${field('输入当前密码确认','••••••••')}${btn('继续使用衣序','ghost')}</div>`),{title:'注销账号',footer:footer('确认注销账号','这是第二次确认。完成后返回登录页，提示「账号已注销」。','danger')});
const legalData={
 'legal-terms':['用户协议',`<p class="hint">衣序（演示版）</p><h2 class="page-title">用户协议</h2><h3>1. 服务与账号</h3><p>衣序提供衣服理解、灵感方向、脚本、图片编辑、笔记和短视频创作辅助。请妥善保管密码及恢复码。</p><h3>2. 点数与生成</h3><p>正式出图、改图与视频按点数记录。提交前展示预估，失败任务退点。一键出片按开拍时的说明自动推进，可中途接手。</p><h3>3. 素材与内容</h3><p>请仅上传有权使用的衣服图、参考图和肖像。不得使用未经授权的他人肖像、侵权素材或内衣泳装等敏感品类内容。</p><h3>4. 使用与终止</h3><p>生成内容商用前应自行核对。你可以删除这组片或注销账号；服务变更及终止会按正式文本说明处理。</p><p class="hint">联系：97000945@qq.com</p>`],
 'legal-privacy':['隐私政策',`<p class="hint">衣序（演示版）</p><h2 class="page-title">隐私政策</h2><h3>1. 我们处理的内容</h3><p>账号资料、上传的衣服图、本人照片与参考图、生成记录，以及提供服务所需的设备和日志信息。</p><h3>2. 用途与第三方</h3><p>用于账号管理与内容创作。生成所需内容会交由阿里云百炼、DeepSeek 处理，仅传递完成生成所需的内容。</p><h3>3. 保存与权利</h3><p>保存期限以正式政策为准。你可以查看资料、删除这组片或注销账号。注销会清理该账号的片场与媒体。</p><h3>4. 未成年人</h3><p>未成年人应在监护人指导下阅读政策、使用服务，并避免上传无权使用的肖像与素材。</p><p class="hint">联系：97000945@qq.com</p>`],
 'legal-disclaimer':['AI 内容免责声明',`<p class="hint">衣序（演示版）</p><h2 class="page-title">AI 内容免责声明</h2><h3>生成结果需要核对</h3><p>图片、视频与文案可能存在错误。衣服还原度以实物为准，商用前请核对款式、面料、人物与文案事实。</p><h3>保留 AI 标识</h3><p>生成内容按《人工智能生成合成内容标识办法》保留可见标识与相关标识信息，发布时请勾选平台 AI 内容声明。</p><h3>改图检查如实呈现</h3><p>「未改到位」表示修改未核对通过，不会自动进入笔记。你仍可主动采用，并在发布清单中看到「手动采用」。</p><p class="hint">联系：97000945@qq.com</p>`]
};
for(const [id,[name,copy]] of Object.entries(legalData))add(id,'paper',body(`${legalTabs(name)}<div class="legal-copy">${copy}</div><div class="notice" style="margin-top:20px">设计摘录 · 正式全文由协议接口提供，不以本页摘录代替。</div>`),{title:'协议与隐私'});
add('about','paper',body(`<div class="stack" style="padding-top:44px;align-items:center">${brand}<p class="section-label">OUTFIT NOTES / DEMO</p><h2 class="display-title" style="font-size:28px;text-align:center">让衣服有故事，<br>让灵感有顺序。</h2><div class="card" style="width:100%;margin-top:24px"><div class="between"><span class="label">版本</span><span class="hint">1.0.0 · 演示版</span></div><div class="divider" style="margin:16px 0"></div><p class="label">服务地址</p><p class="hint" style="margin-top:6px">运行时读取当前配置</p></div><div style="width:100%">${listRow('file','用户协议')}${listRow('lock','隐私政策')}${listRow('spark','AI 内容免责声明')}</div><p class="hint">联系：97000945@qq.com</p></div>`),{title:'关于衣序'});
const annotations=JSON.parse(await readFile(path.join(root,'pages.json'),'utf8'));
const sections=[['entry','01','先认识，再开始','隐私提示、三屏引导与账号入口。',0,7],['studio','02','在片场，找到灵感','首页与两种开拍模式。',7,10],['direct','03','把想法，一步步拍出来','沉浸编导与自动推进，过程透明且可恢复。',10,14],['edit','04','留住细节，也留住判断','版本、局部改、挑图与未通过版本的主动确认。',14,18],['publish','05','整理好，再分享','笔记、草稿冲突、发布清单与视频。',18,23],['personal','06','你的片场，你的账号','片场管理、个人档案、设置与账号闭环。',23,31],['legal','07','把约定，说清楚','协议、隐私、AI 声明与关于。',31,35]];
const esc=s=>s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const specimen=(s,i)=>{const a=annotations.find(p=>p.id===s.id);if(!a)throw new Error(`Missing ${s.id}`);return `<article class="specimen" id="${s.id}" data-page="${s.id}">${s.html}<aside class="annotation"><p class="screen-id">SCREEN ${String(i+1).padStart(2,'0')} / ${s.theme.toUpperCase()}</p><h3>${esc(a.title)}</h3><div class="rule"></div><h4>设计要点</h4><p>${esc(a.layout)}</p><h4>状态变体</h4><p>${esc(a.states.error)}</p><h4>文案</h4><p>「${esc(a.copy[0])}」</p><span class="tag">390 × 844</span><p class="small" style="margin-top:12px">${esc(a.contract)}</p></aside></article>`;};
const symbols={back:'<path d="m14 5-7 7 7 7M7 12h14"/>',chevron:'<path d="m9 5 7 7-7 7"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',up:'<path d="M12 19V5m-6 6 6-6 6 6"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',person:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',shirt:'<path d="m8 3-5 4 3 5 2-1v10h8V11l2 1 3-5-5-4a4 4 0 0 1-8 0Z"/>',settings:'<path d="m9 3-1 3-3 1v4l-2 1 2 3v4l3-1 2 3 4-1 2-2 3 1 2-4-2-2 1-4-3-1-2-3Z"/><circle cx="12" cy="12" r="3"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4 2c-1.5 1-1.5 1.5-1.5 3M12 17h.01"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',key:'<circle cx="8" cy="8" r="5"/><path d="m12 12 9 9m-3-3 2-2m-5-1 2-2"/>',spark:'<path d="m12 2 2.8 7.2L22 12l-7.2 2.8L12 22l-2.8-7.2L2 12l7.2-2.8Z"/>',refresh:'<path d="M20 11a8 8 0 1 0-2 7M20 4v7h-7"/>',pencil:'<path d="m15 3 6 6-12 12H3v-6ZM12 6l6 6"/>',select:'<rect x="4" y="4" width="16" height="16" rx="2" stroke-dasharray="3 3"/>',undo:'<path d="M4 10h10a6 6 0 0 1 0 12M4 10l5-5m-5 5 5 5"/>',quote:'<path d="M4 5h16v12H9l-5 4ZM8 9h8M8 13h5"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',compare:'<path d="M12 2v20M9 5H3v14h6m6-14h6v14h-6"/>',play:'<path d="m8 4 13 8-13 8Z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',file:'<path d="M5 3h10l4 4v14H5ZM15 3v5h4M8 12h8m-8 4h6"/>',signal:'<path d="M3 20v-4m5 4v-8m5 8V8m5 12V3"/>',wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-11 4a6 6 0 0 1 8 0m-4 4h.01"/>'};
const html=`<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>衣序 · UI 设计板</title><style>${styles}</style></head><body data-board-theme="paper"><svg class="defs" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><defs>${Object.entries(symbols).map(([n,s])=>`<symbol id="i-${n}" viewBox="0 0 24 24">${s}</symbol>`).join('')}</defs></svg><header class="masthead"><div><p class="eyebrow">YIXU / PRODUCT DESIGN SPECIFICATION</p><h1>让灵感，<span>有顺序。</span></h1><p class="intro">衣序 · 从一件衣服，到一组有故事的穿搭成片。<br>一份覆盖创作、判断与发布的完整移动端设计。</p></div><div class="cover-note"><p>片场是暗的，<br>编辑桌是亮的。</p><small>35 个页面画布 · 390 × 844<br>按场景呈现 studio / paper 两套主题<br>静态设计评审，按钮仅作视觉示意。</small></div></header><div class="toolbar"><nav class="nav" aria-label="设计板目录"><a href="#flow-entry">01 首次进入</a><a href="#flow-studio">02 片场</a><a href="#flow-direct">03 编导</a><a href="#flow-edit">04 改图</a><a href="#flow-publish">05 发布</a><a href="#flow-personal">06 账号</a><a href="#flow-legal">07 约定</a></nav><div class="preview-controls" role="group" aria-label="主题预览"><button data-preview="default" aria-pressed="true">按场景</button><button data-preview="paper" aria-pressed="false">全部浅色</button><button data-preview="studio" aria-pressed="false">全部深色</button></div></div><main class="board">${sections.map(([id,n,title,sub,from,to])=>`<section class="flow-section" id="flow-${id}">${sectionTitle(n,title,sub)}<div class="screen-grid">${screens.slice(from,to).map((s,j)=>specimen(s,from+j)).join('')}</div></section>`).join('')}<footer class="board-end"><p>衣序 · 设计交付 / 页面、状态、组件共同组成实现依据。</p><a href="../UI设计稿.md">阅读完整 UI 设计稿 ↗</a></footer></main><script>document.querySelectorAll('[data-preview]').forEach(button=>button.addEventListener('click',()=>{const mode=button.dataset.preview;document.querySelectorAll('[data-preview]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('.screen:not([data-theme-locked])').forEach(s=>s.dataset.theme=mode==='default'?s.dataset.defaultTheme:mode);document.body.dataset.boardTheme=mode==='studio'?'studio':'paper';}));</script></body></html>`;
await mkdir(root,{recursive:true});
await writeFile(path.join(root,'index.html'),html);
console.log(`Built ${screens.length} static screens.`);
